"""Cooperative cancellation uses generated files and leaves originals intact."""
from __future__ import annotations

import hashlib
import tempfile
import threading
import unittest
from pathlib import Path
from unittest.mock import patch

from PIL import Image

import app
import scanner


class ScannerStopTests(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory()
        self.root = Path(self.temporary.name)
        self.stop = threading.Event()

    def tearDown(self):
        self.temporary.cleanup()

    def image(self, name="image.png", color="blue"):
        path = self.root / name
        Image.new("RGB", (32, 24), color).save(path)
        return path

    def scan(self, progress=None):
        return scanner.scan_folder(self.root, on_progress=progress, should_stop=self.stop.is_set)

    def test_already_stopped_discovers_no_files_and_has_no_errors(self):
        self.image()
        self.stop.set()
        result = self.scan()
        self.assertTrue(result.stopped)
        self.assertFalse(result.photos)
        self.assertFalse(result.errors)
        self.assertEqual(result.stats["total"], 0)

    def test_discovery_checks_during_enumeration(self):
        class Entry:
            name = "unused"

        class Entries:
            consumed = 0

            def __enter__(inner):
                return inner

            def __exit__(inner, *_):
                return False

            def __iter__(inner):
                for _ in range(10000):
                    inner.consumed += 1
                    if inner.consumed == 4:
                        self.stop.set()
                    yield Entry()

        entries = Entries()
        with patch("scanner.os.scandir", return_value=entries):
            paths, errors = scanner.discover(self.root, True, should_stop=self.stop.is_set)
        self.assertLess(entries.consumed, 10)
        self.assertEqual((paths, errors), ([], []))

    def test_hash_checks_each_chunk_and_does_not_return_partial_digest(self):
        class Source:
            reads = 0

            def __enter__(inner):
                return inner

            def __exit__(inner, *_):
                return False

            def read(inner, size):
                self.assertEqual(size, 1024 * 1024)
                inner.reads += 1
                self.stop.set()
                return b"generated bytes"

        source = Source()
        with patch.object(Path, "open", return_value=source):
            with self.assertRaises(scanner.ScanCancelled):
                scanner.hash_file(self.root / "generated.bin", self.stop.is_set)
        self.assertEqual(source.reads, 1)

    def test_normal_hash_signature_remains_compatible(self):
        path = self.root / "generated.bin"
        path.write_bytes(b"generated bytes")
        expected = hashlib.sha256(b"generated bytes").hexdigest()
        self.assertEqual(scanner.hash_file(path), expected)
        self.assertEqual(scanner.hash_file(path, lambda: False), expected)

    def test_cancel_after_decode_skips_ocr_and_incomplete_photo(self):
        path = self.image()
        original = path.read_bytes()
        decode = scanner.oriented_image

        def decoded(*args):
            image = decode(*args)
            self.stop.set()
            return image

        with patch("scanner.oriented_image", side_effect=decoded), patch("scanner.classify_image") as classify:
            result = self.scan()
        classify.assert_not_called()
        self.assertTrue(result.stopped)
        self.assertFalse(result.photos)
        self.assertFalse(result.errors)
        self.assertEqual(path.read_bytes(), original)

    def test_cancel_after_classification_skips_text_and_vectors(self):
        self.image()

        def classified(*_):
            self.stop.set()
            return [], [], "no-text"

        with patch("scanner.classify_image", side_effect=classified), \
                patch("scanner.extract_image_text") as text, patch("scanner.visual_search.embed_image") as vector:
            result = self.scan()
        text.assert_not_called()
        vector.assert_not_called()
        self.assertTrue(result.stopped)
        self.assertFalse(result.photos)
        self.assertFalse(result.errors)

    def test_cancel_after_text_skips_vectors_and_discards_private_index(self):
        self.image()

        def text(*_):
            self.stop.set()
            return "Private generated words", "indexed"

        with patch("scanner.classify_image", return_value=([], [], "no-text")), \
                patch("scanner.extract_image_text", side_effect=text), \
                patch("scanner.visual_search.embed_image") as vector:
            result = self.scan()
        vector.assert_not_called()
        self.assertTrue(result.stopped)
        self.assertFalse(result.photos)
        self.assertFalse(result.errors)

    def test_cancel_after_vectors_is_not_swallowed_as_model_failure(self):
        self.image()

        def vector(*_):
            self.stop.set()
            return (1.0,) * 512

        with patch("scanner.classify_image", return_value=([], [], "no-text")), \
                patch("scanner.extract_image_text", return_value=("Generated", "indexed")), \
                patch("scanner.visual_search.embed_image", side_effect=vector):
            result = self.scan()
        self.assertTrue(result.stopped)
        self.assertFalse(result.photos)
        self.assertFalse(result.errors)

    def test_completed_files_keep_exact_groups_and_originals_unchanged(self):
        for name in ("a.bin", "b.bin", "c.bin"):
            (self.root / name).write_bytes(b"same generated bytes")
        before = {path.name: path.read_bytes() for path in self.root.iterdir()}

        def progress(done, total, phase):
            if phase == "read" and done == 2:
                self.stop.set()

        result = self.scan(progress)
        self.assertTrue(result.stopped)
        self.assertEqual(len(result.photos), 2)
        self.assertEqual([group["kind"] for group in result.groups], ["exact"])
        self.assertFalse(result.errors)
        self.assertEqual(before, {path.name: path.read_bytes() for path in self.root.iterdir()})

    def test_cancel_before_similarity_retains_all_pixel_and_exact_groups(self):
        first = self.image("a.png")
        (self.root / "b.png").write_bytes(first.read_bytes())
        Image.open(first).save(self.root / "c.bmp")

        def progress(done, total, phase):
            if phase == "compare":
                self.stop.set()

        with patch("scanner.classify_image", return_value=([], [], "no-text")), \
                patch("scanner.extract_image_text", return_value=("", "empty")), \
                patch("scanner.visual_search.embed_image", return_value=None), \
                patch("scanner.visual_search.capabilities", return_value={"available": False}):
            result = self.scan(progress)
        self.assertTrue(result.stopped)
        self.assertEqual(len(result.photos), 3)
        self.assertEqual({group["kind"] for group in result.groups}, {"exact", "pixels"})

    def test_similarity_checks_every_pair_and_keeps_already_matched_pairs(self):
        photos = {}
        for number in range(4):
            photo = scanner.Photo(str(number), self.root / str(number), str(number), str(number), 1, (0, 0, 1, 0),
                                  sha256=str(number), width=48, height=48, pixel_hash=str(number),
                                  sample=bytes((80 + number,)) * (48 * 48 * 3))
            photos[photo.id] = photo
        original = scanner._group

        def group(kind, *args):
            value = original(kind, *args)
            if kind == "similar":
                self.stop.set()
            return value

        with patch("scanner._group", side_effect=group):
            groups = scanner.compare_photos(photos, should_stop=self.stop.is_set)
        self.assertEqual(len(groups), 1)
        self.assertEqual(groups[0]["kind"], "similar")

    def test_stopped_progress_reports_fully_completed_count(self):
        for name in ("a.bin", "b.bin"):
            (self.root / name).write_bytes(b"generated")
        events = []

        def progress(done, total, phase):
            events.append((done, total, phase))
            if phase == "read":
                self.stop.set()

        self.scan(progress)
        self.assertEqual(events[-1], (1, 2, "stopped"))
        self.assertNotIn("complete", [item[2] for item in events])


class AppStopTests(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory()
        self.root = Path(self.temporary.name)
        (self.root / "generated.bin").write_bytes(b"generated")
        self.review = app.ReviewApp(self.root)

    def tearDown(self):
        self.review.close()
        self.temporary.cleanup()

    def join_scan(self):
        self.review.scan_thread.join(timeout=5)
        self.assertFalse(self.review.scan_thread.is_alive())

    def test_idle_stop_does_not_scan_or_create_stores(self):
        with patch("app.scan_folder") as scan:
            reply = self.review.stop_scan()
        self.assertFalse(reply["accepted"])
        self.assertFalse(reply["state"]["stopRequested"])
        self.assertFalse(reply["state"]["scanStopped"])
        self.assertIsNone(self.review.store)
        scan.assert_not_called()

    def test_stop_is_idempotent_blocks_overlaps_and_next_run_uses_fresh_event(self):
        entered, release = threading.Event(), threading.Event()
        real_scan = scanner.scan_folder

        def paused(*args, **kwargs):
            entered.set()
            if not release.wait(5):
                raise RuntimeError("Generated barrier not released")
            return real_scan(*args, **kwargs)

        with patch("app.scan_folder", side_effect=paused):
            self.review.start_scan(self.root)
            self.assertTrue(entered.wait(3))
            old_event = self.review.scan_stop_event
            reply = self.review.stop_scan()
            self.assertTrue(reply["accepted"])
            self.assertEqual(reply["state"]["progress"]["phase"], "stopping")
            self.assertTrue(reply["state"]["scanning"])
            self.assertTrue(reply["state"]["stopRequested"])
            self.assertFalse(self.review.stop_scan()["accepted"])
            with self.assertRaises(app.ReviewError):
                self.review.start_scan(self.root)
            self.review._progress(0, 1, "read", self.review.scan_generation, old_event)
            self.assertEqual(self.review.state()["progress"]["phase"], "stopping")
            release.set()
            self.join_scan()
        stopped = self.review.state()
        self.assertTrue(stopped["scanStopped"])
        self.assertFalse(stopped["stopRequested"])
        self.assertFalse(stopped["scanning"])
        self.assertEqual(stopped["progress"]["phase"], "stopped")
        self.assertFalse(stopped["errors"])
        self.assertFalse(self.review.stop_scan()["accepted"])
        self.review.start_scan(self.root)
        self.join_scan()
        self.assertIsNot(self.review.scan_stop_event, old_event)
        self.assertFalse(self.review.scan_stop_event.is_set())
        self.assertFalse(self.review.state()["scanStopped"])
        self.assertEqual(self.review.state()["stats"]["total"], 1)
        self.assertEqual(self.review.state()["progress"]["phase"], "complete")

    def test_close_signals_worker_without_locking_out_its_progress_or_late_publish(self):
        entered, release = threading.Event(), threading.Event()
        real_scan = scanner.scan_folder

        def paused(*args, **kwargs):
            entered.set()
            if not release.wait(5):
                raise RuntimeError("Generated barrier not released")
            kwargs["on_progress"] = args[3]
            return real_scan(args[0], args[1], args[2], **kwargs)

        with patch("app.scan_folder", side_effect=paused):
            self.review.start_scan(self.root)
            self.assertTrue(entered.wait(3))
            closing = threading.Thread(target=self.review.close)
            closing.start()
            self.assertTrue(self.review.scan_stop_event.wait(3))
            with self.review.lock:
                self.assertTrue(self.review.closing)
                before = self.review.result
            release.set()
            closing.join(5)
            self.assertFalse(closing.is_alive())
        self.assertIs(self.review.result, before)
        self.assertFalse(self.review.state()["scanning"])
        self.assertFalse(self.review.result.photos)
        self.assertFalse(self.review.result.errors)


if __name__ == "__main__":
    unittest.main()
